+ */
+export const useIframeUrlSync = ({
+  basePath,
+  enabled,
+  entrySrc,
+  iframeRef,
+  isAllowedPath,
+}: UseIframeUrlSyncOptions): { initialSrc: string } => {
+  const splat = useParams()["*"] ?? "";
